input.newString:
for set in &sets {
    let slice = os_str_as_bytes(set)?;

    // A trailing backslash is escaped if the total number of consecutive
    // trailing backslashes is even.
    if slice.iter().rev().take_while(|&&c| c == b'\\').count() % 2 == 1 {
        show!(USimpleError::new(
            0,
            "warning: an unescaped backslash at end of string is not portable"
        ));
    }
}

